    // Set the mode
    SPIMode  ( _Mode_ [, SPIClockMode]) //Legacy SPI
    SPIMode  ( _Mode_ , SPIClockMode)   //18FxxQxx, 18FxxK42 and 18xxFK83 microcontrollers

    // Send bytge and receive data byte
    SPITransfer (  _OutByte_, _InByte_ )

    // Send data byte
    FastHWSPITransfer( _OutByte_ )

    // USe MASTERSLOW | MASTER | MASTERFAST | MASTERULTRAFAST for specific AVRs only | MasterSSPADDMode for specific PICs SSPADD support

    // The system constant `HWSPIMode` defaults to MASTERFAST when microcontroller frequency less or equal to 32 mhz
    // Defaults to MASTER when microcontroller frequency more than 32 mhz.
    // To change use the following method
    #define HWSPIMode MASTERULTRAFAST

    // Set the mode
    SPIMode2  ( _Mode_ [, SPIClockMode]) //Legacy SPI
    SPIMode2  ( _Mode_ , SPIClockMode)   //18FxxQxx, 18FxxK42 and 18xxFK83 microcontrollers

    // Send bytge and receive data byte
    SPITransfer2 (  _OutByte_, _InByte_ )

    // Send data byte
    FastHWSPITransfer2( _OutByte_ )

    SPIMode ( _Mode_ [, _SPIClockMode_])

    // Specfic the hardware SPI operating mode, can be MasterFast, Master, MasterSlow
    #DEFINE HWSPIMode   MasterFast

    // You can use a shared constant to set a consant with the desired SPIClockMode
    #DEFINE HWSPIClockMode  SPI_CPOL_0 + SPI_CPHA_0

    SPIMode ( _Mode_ , _SPIClockMode_ )

    // Specfic the hardware SPI operating mode, can be MasterUltraFast, MasterFast, Master, MasterSlow
    #DEFINE HWSPIMode   MasterUltraFast

    // You can use a shared constant to set a consant with the desired SPIClockMode
    #DEFINE HWSPIClockMode  SPI_SS_0 + SPI_CPOL_0 + SPI_CPHA_0

    // Optionally change the SPI BAUD RATE from 4000
        #DEFINE SPI_BAUD_RATE 8000

    // Optionally update the SPI baud rate register with an explicit value
    //  typical use is to entry a specific calculated value
        #DEFINE SPI_BAUD_RATE_REGISTER  55

    #CHIP 18F16Q41,64

    #STARTUP InitPPS, 85
    #DEFINE PPSToolPart 18F16Q41

    // Use PPS to assign SPI capabilities to specific ports
    SUB InitPPS
        SPI1SDIPPS = 0x000C
        RB6PPS = 0x001B
        SPI1SCKPPS = 0x000E
        RB5PPS = 0x001C
        RC6PPS = 0x001D
        SPI1SSPPS = 0x0016
    END SUB


    // Optionally change the SPI BAUD RATE from 4000
        // #DEFINE SPI_BAUD_RATE 8000

    // Optionally update the SPI baud rate register with an explicit value
    //  typical use is to entry a specific calculated value
        // #DEFINE SPI_BAUD_RATE_REGISTER  1

    // Specfic the hardware SPI operating model
    // Can be MasterUltraFast, MasterFast, Master, MasterSlow
    #DEFINE HWSPIMode   MasterUltraFast

    // You can use a shared constant to set a consant with the desired SPIClockMode
    #DEFINE HWSPIClockMode  SPI_SS_0 + SPI_CPOL_0 + SPI_CPHA_0

    // Call SPIMode
    SPIMode (HWSPIMode,  HWSPIClockMode )

    // Define the GCBASIC required SPI port constants.
    // Must match any PPS defined.
    #DEFINE SPI_SCK   PORTB.6
    #DEFINE SPI_DO    PORTB.5
    #DEFINE SPI_DI    PORTB.4
    #DEFINE SPI_DC    PortC.1
    #DEFINE SPI_CS    PortC.6
    #DEFINE SPI_RESET PortC.2

    DO
        // Send 0x75 via SPI over and over again...
        FastHWSPITransfer 0x75          ' <<< the FastHWSPITransfer instruction
    LOOP

    SPI2Mode ( _Mode_ [, _SPIClockMode_])

    // Specfic the hardware SPI operating mode, can be MasterFast, Master, MasterSlow
    #DEFINE HWSPI2Mode   MasterFast

    // You can use a shared constant to set a consant with the desired SPIClockMode
    #DEFINE HWSPI2ClockMode  SPI_CPOL_0 + SPI_CPHA_0

    SPI2Mode ( _Mode_ , _SPIClockMode_ )

    // Specfic the hardware SPI operating mode, can be MasterUltraFast, MasterFast, Master, MasterSlow
    #DEFINE HWSPI2Mode   MasterUltraFast

    // You can use a shared constant to set a consant with the desired SPIClockMode
    #DEFINE HWSPI2ClockMode  SPI_SS_0 + SPI_CPOL_0 + SPI_CPHA_0

    // Optionally change the SPI BAUD RATE from 4000
        #DEFINE SPI2_BAUD_RATE 8000

    // Optionally update the SPI baud rate register with an explicit value
    //  typical use is to entry a specific calculated value
        #DEFINE SPI2_BAUD_RATE_REGISTER  55

    #CHIP 18F16Q41,64

    #STARTUP InitPPS, 85
    #DEFINE PPSToolPart 18F16Q41

    // Use PPS to assign SPI capabilities to specific ports
    // NOTE: the RxxPPS pin assignments and function-selector values below are illustrative -
    // confirm the correct pins and PPS function values for SPI2 on your specific device datasheet.
    SUB InitPPS
        SPI2SDIPPS = 0x000C
        RB6PPS = 0x001B
        SPI2SCKPPS = 0x000E
        RB5PPS = 0x001C
        RC6PPS = 0x001D
        SPI2SSPPS = 0x0016
    END SUB


    // Optionally change the SPI BAUD RATE from 4000
        // #DEFINE SPI2_BAUD_RATE 8000

    // Optionally update the SPI baud rate register with an explicit value
    //  typical use is to entry a specific calculated value
        // #DEFINE SPI2_BAUD_RATE_REGISTER  1

    // Specfic the hardware SPI operating model
    // Can be MasterUltraFast, MasterFast, Master, MasterSlow
    #DEFINE HWSPI2Mode   MasterUltraFast

    // You can use a shared constant to set a consant with the desired SPIClockMode
    #DEFINE HWSPI2ClockMode  SPI_SS_0 + SPI_CPOL_0 + SPI_CPHA_0

    // Call SPI2Mode
    SPI2Mode (HWSPI2Mode,  HWSPI2ClockMode )

    // Define the GCBASIC required SPI port constants.
    // Must match any PPS defined.
    #DEFINE SPI2_SCK   PORTB.6
    #DEFINE SPI2_DO    PORTB.5
    #DEFINE SPI2_DI    PORTB.4
    #DEFINE SPI2_DC    PortC.1
    #DEFINE SPI2_CS    PortC.6
    #DEFINE SPI2_RESET PortC.2

    DO
        // Send 0x75 via SPI over and over again...
        FastHWSPI2Transfer 0x75          ' <<< the FastHWSPI2Transfer instruction
    LOOP

    // you must define software I2C or hardware I2C. I2C2 is not currently supported (as of January 2023)
    // Include this specific library. This is mandated
    #INCLUDE <PCF8574.H>

    //! send a variable to the I2C device that sets the device ports
    PCF8574_sendbyte(PCF8574_DEVICE_1, LEDStatus )          ' <<< the PCF8574_sendbyte instruction this page documents

    //! read the status of the port into the variable Portstatus
    PCF8574_readbyte(PCF8574_DEVICE_1, PortStatus )

section.simpara:
Not all of these timers available on all microcontrollers. For example,
if a microcontroller has three timers, then typically only Timer0,
Timer1 and Timer2 will be available.

section.programlisting:
    'Please check configuration before using on an alternative microcontroller.

    #chip 16f18855,32
    #option explicit

    'Set the PPS of the I2C and the RS232 ports.
    #startup InitPPS, 85
    Sub InitPPS
      UNLOCKPPS          ' <<< the UnLockPPS instruction
        RC0PPS = 0x0010       'RC0->EUSART:TX;
        RXPPS  = 0x0011       'RC1->EUSART:RX;

        SSP1CLKPPS = 0x14     'RC3->MSSP1:SCL1;
        SSP1DATPPS = 0x13     'RC4->MSSP1:SDA1;
        RC3PPS = 0x15         'RC3->MSSP1:SCL1;
        RC4PPS = 0x14         'RC4->MSSP1:SDA1;
      LOCKPPS
    End Sub

    #chip 16f18855,85
    #option explicit

    'Set the PPS of the I2C and the RS232 ports.
    #startup InitPPS, 85
    Sub InitPPS
      UNLOCKPPS          ' <<< the UnLockPPS instruction
        RC0PPS = 0x0010       'RC0->EUSART:TX;
        RXPPS  = 0x0011       'RC1->EUSART:RX;

        SSP1CLKPPS = 0x14     'RC3->MSSP1:SCL1;
        SSP1DATPPS = 0x13     'RC4->MSSP1:SDA1;
        RC3PPS = 0x15         'RC3->MSSP1:SCL1;
        RC4PPS = 0x14         'RC4->MSSP1:SDA1;
      LockPPS
    End Sub

    #chip 16f18855,32
    #option explicit

    'Set the PPS of the I2C and the RS232 ports.
    #startup InitPPS, 85
    Sub InitPPS
      UNLOCKPPS
        RC0PPS = 0x0010       'RC0->EUSART:TX;
        RXPPS  = 0x0011       'RC1->EUSART:RX;

        SSP1CLKPPS = 0x14     'RC3->MSSP1:SCL1;
        SSP1DATPPS = 0x13     'RC4->MSSP1:SDA1;
        RC3PPS = 0x15         'RC3->MSSP1:SCL1;
        RC4PPS = 0x14         'RC4->MSSP1:SDA1;
      LOCKPPS          ' <<< the LockPPS instruction
    End Sub

#chip MEGA4809 #option Explicit
// Numeric constants #define LENGTH 20 #define CONTROL 0x19,7 #define SINGLEPI = 22/7 // evaluated numeric string #define INTPI = INT(22/7) // evaluated numeric string #define FACTOREDPI = INT((22/7 - INT(22/7))*1000) // evaluated numeric string #define LENGTHSQUARED = LENGTH * LENGTH // evaluated numeric string #define PI 3.142 #define RADIUS 10 #define CIRCUMFERENCECALC = PI * RADIUS // evaluated numeric string, with constant substitution #define FACTORISEDCIRCUMFERENCE = INT(CIRCUMFERENCECALC*100) // evaluated numeric string, with constant substitution
//String(s) require double quotes and NO `=` assignment #define MYSTRING "This is a string" // A string assignment is not required #define ACONSTANTTHATEXISTS
// Macros are not supported.. just define the sub! // #define BADPOSITION(XX,YY,ZZ) (YY-(2 * ZZ +XX))
// Unused constants that are invalid may not report an error until you try to use them within your program - as in this example // String assignment with an equal sign will fail. Do not use `=` #define BADMYSTRING = "This is a string"
#script //Scripts can modify and manage CONSTANTS
// Warning can be used to show values during compilation WARNING LENGTH WARNING CONTROL WARNING SINGLEPI WARNING INTPI WARNING FACTOREDPI WARNING MYSTRING
If DEF(ACONSTANTTHATEXISTS) Then WARNING "The constant ACONSTANTTHATEXISTS exists" End If
// Test for a value in the [ChipData] section of the DAT file. Always has the prefix CHIP If DEF(CHIPAVRDX) Then WARNING "This is an AVRDX chip" End If
// Good practice constant testing, see the code below for BAD and GOOD practice
// Set the constant to 0 so we can use this to test for validity // Use the prefix SCRIPT as this is clear in the program SCRIPTAN1CONSTANT = 0 If DEF(AVRDX) Then // Is this an AVRDx chip If DEF(AIN1) Then SCRIPTAN1CONSTANT = AIN1 End If End If If NODEF(AVRDX) Then // This is NOT an AVRDx chip If DEF(AVR) Then // This is an AVR SCRIPTAN1CONSTANT = AN1 End If If DEF(PIC) Then // This is a PIC SCRIPTAN1CONSTANT = ANA1 End If End If // Now validate the result If SCRIPTAN1CONSTANT = 0 Then WARNING Script has determined that no valid ADC port exists, or some other message End If
#endscript
// Some conditional examples
#IF DEF( CONSTANTTHATEXISTS ) //! Cause a compiler error - as the constant exists. Remove comment to test #ELSE //! Cause a compiler error - as the constant does not exist. Remove comment to test #ENDIF
#IFDEF Oneof(CHIP_18F24K40,CHIP_18F25K40,CHIP_18F26K40,CHIP_18F27K40,CHIP_18F45K40,CHIP_18F46K40,CHIP_18F47K40,CHIP_18F65K40,CHIP_18F66K40,CHIP_18LF24K40, CHIP_18LF25K40, CHIP_18LF26K40, CHIP_18LF27K40, CHIP_18LF45K40, CHIP_18LF46K40, CHIP_18LF47K40, CHIP_18F65K40, CHIP_18LF65K40, CHIP_18F66K40, CHIP_18LF66K40, CHIP_18F67K40, CHIP_18LF67K40 ) //~ Do something #ENDIF
dim myStringVar as String myStringVar = MYSTRING ' <<< assigning a string-type #define to a String variable
// BAD PRACTICE - code is hard to understand // Use constant testing to determine the correct ADC to read. Bad practice, see the #SCRIPT section dim mybyteVar as Byte #IF DEF(AIN1) mybyteVar = readAD( AIN1 ) #ELSE #IF DEF(ANA1) mybyteVar = readAD( ANA1 ) #ELSE mybyteVar = readAD( AN1 ) #ENDIF #ENDIF
// GOOD PRACTICE dim mybyteVar as Byte mybyteVar = readAD( SCRIPTAN1CONSTANT )
dim myArray(2) myArray = CONTROL

    #chip 16f18855,32
    #option explicit

    'Set the PPS of the I2C and the RS232 ports.
    #startup InitPPS, 85          ' <<< registering InitPPS to run automatically at startup, before priority-90 routines
    Sub InitPPS
      RC0PPS = 0x0010       'RC0->EUSART:TX;
      RXPPS  = 0x0011       'RC1->EUSART:RX;

      SSP1CLKPPS = 0x14     'RC3->MSSP1:SCL1;
      SSP1DATPPS = 0x13     'RC4->MSSP1:SDA1;
      RC3PPS = 0x15         'RC3->MSSP1:SCL1;
      RC4PPS = 0x14         'RC4->MSSP1:SDA1;
    End Sub

    #chip 16F1937
    // #chip mega4809
    // #chip mega328p, 16


    // Add PPS if appropriate for your chip
    // [change to your config] This is the config for a serial terminal

    // assumes USART1 ( or USART0 on AVRDx ), if you select USART1/2/3/4 then you MUST add the comport parameter to all HSerxxxxx functions.
    // turn on the RS232 and terminal port.
    // Define the USART settings
    #DEFINE USART_BAUD_RATE 9600
    #DEFINE USART_BLOCKING  // Required, could use #define USART_TX_BLOCKING as the RX is interrupt driven.

    // This assumes you are using an ANSI compatible terminal.  Use PUTTY.EXE, it is very easy to use.

    //   Main program

    // Wait for terminal to settle
    wait 3 s

    // Create the supporting variables
    Dim next_in As Byte
    Dim next_out As Byte
    Dim syncbyte As Byte
    Dim temppnt As Byte

    // Constants etc required for Buffer Ring
    #DEFINE BUFFER_SIZE 8
    #DEFINE bkbhit (next_in <> next_out)

    // Define the Buffer
    Dim buffer( BUFFER_SIZE - 1 ) // we will use element 0 in the array as part of our buffer

    // Call init the buffer
    InitBufferRing

    HSerSend 10
    HSerSend 13
    HSerSend 10
    HSerSend 13
    HSerPrint "Started: Serial between two devices"
    HSerSend 10
    HSerSend 13


    // Get character(s) and send back
    Do

        //  Do we have data in the buffer?
        if bkbhit then

            // Send the next character in the buffer to the terminal, exposed via the function `bgetc`          ' <<< draining the buffer ring one character at a time
            HSerSend bgetc

        end if
    Loop


    // Supporting subroutines

    Sub readUSART

        buffer(next_in) = HSerReceive
        temppnt = next_in
        next_in = ( next_in + 1 ) % BUFFER_SIZE
        If ( next_in = next_out ) Then  // buffer is full!!
            next_in = temppnt
        End If

    End Sub

    Function bgetc
        Dim local_next_out as Byte    // maintain a local copy of the next_out variable to ensure it does not change when an Interrupt happens
        local_next_out = next_out
        bgetc = buffer(local_next_out)
        local_next_out=(local_next_out+1) % BUFFER_SIZE
        INTOFF
        next_out = local_next_out
        INTON
    End Function




    Sub InitBufferRing

        // Set the buffer to the first address
        next_in = 0
        next_out = 0
        // Interrupt Handler - some have RCIE and some have U1RXIE, so handle
        //
        // You would need to change the Interrupt if you use USART1,2,3, or 4
        //
        #IFDEF BIT( RCIE )
            On Interrupt UsartRX1Ready Call readUSART
        #ENDIF
        #IFDEF BIT( U1RXIE )
            On Interrupt UART1ReceiveInterrupt Call readUSART
        #ENDIF

        #IFDEF AVR
            #IFNDEF CHIPAVRDX
                //~ Support for legacy AVR
                On Interrupt UsartRX1Ready Call readUSART
            #ELSE
                //~ Support for AVRDx - AVRDx chips are USART0,USART1,USART2,USART3 and USART4 not USART.
                On Interrupt Usart0RXReady Call readUSART
            #ENDIF
        #ENDIF

    End Sub

        #CHIP 18F16Q41
        #OPTION EXPLICIT

        ; -----  Add the following line to USE.ini ------------------
        ;
        ;        conditionaldebugfile = IFDEF_TEST.gcb
        ;
        ; -----------------------------------------------------------

        #IFDEF PIC
            #IFDEF ONEOF(CHIP_18F15Q41, CHIP_18F16Q41)
                #IF CHIPRAM = 2048  'TRUE
                    #IF CHIPWORDS = 32768 ' TRUE
                        #IFDEF VAR(NVMLOCK) 'TRUE
                            #IFDEF VAR(OSCCON2)  'TRUE
                                #IFDEF  VAR(NVMCON0)  'TRUE    set var1 to 1
                                    DIM _VAR1
                                    _VAR1 = 1
                                #ENDIF
                            #ENDIF
                        #ENDIF
                    #ENDIF
                #ENDIF

                #IF CHIPRAM = 4096  'TRUE
                    #IF CHIPWORDS = 32768 ' TRUE
                        #IFDEF VAR(NVMLOCK) 'TRUE
                            #IFDEF VAR(OSCCON2)  'TRUE
                                #IFDEF  VAR(NVMCON0)  'TRUE   = set var1 to 0
                                    DIM _VAR1
                                    _VAR1 = 0          ' <<< the assignment the debug trace below confirms actually executes
                                #ENDIF
                            #ENDIF
                        #ENDIF
                    #ENDIF
                #ENDIF
            #ENDIF
        #ENDIF

        Do
        Loop

        // ===============================================
        // ***  Below is debugger output for this file ***
        // ===============================================

        // GCBASIC (0.99.02 2022-07-21 (Windows 32 bit) : Build 1143)

        // Compiling c:\Users\admin\Downloads\IFDEF_TEST.gcb

        //               13: #IFDEF PIC
        //               15: #IFDEF ONEOF(CHIP_18F15Q41, CHIP_18F16Q41)
        //               17: #IF CHIPRAM = 2048
        //               19: #IF CHIPWORDS = 32768
        //               21: #IFDEF VAR(NVMLOCK)
        //               23: #IFDEF VAR(OSCCON2)
